/** The signature Settings shows before the practice writes its own: never put on an email. */
const PLACEHOLDER_SIGNATURE = '--\\nSystem Generated'

/**
 * How the assistant speaks for the practice: the firm's name (Settings, or the
 * firm's details), the tone, the email signature and the disclaimer chosen in
 * Settings. A signature or disclaimer the practice hasn't written is left out.
 */
export function firmIdentity(db: Database): { firm: string; voice: string; signature: string | null; disclaimer: string | null; currency: string } {
  const setting = (key: string): string | null => {
    const v = (db.prepare('SELECT value FROM app_settings WHERE key = ?').get(key) as { value: string } | undefined)?.value?.trim()
    return v || null
  }
  const signature = setting('email_signature')
  return {
    firm: setting('firm_name') ?? firmName(db) ?? 'the practice',
    voice: setting('brand_voice') ?? 'Corporate',
    signature: signature && signature !== PLACEHOLDER_SIGNATURE ? signature.replace(/\\n/g, '\n') : null,
    disclaimer: setting('legal_disclaimer_active') === 'true' ? setting('disclaimer_text') : null,
    currency: setting('preferred_currency') ?? 'GBP'
  }
}

