case 'get_overdue_clients': {
  // Clients with overdue deadlines, most overdue first, from the same list as Compliance → Deadlines.
  const byClient = new Map<string, { ref: string; client_name: string; overdue: number; oldest_days_late: number; deadlines: string[] }>()
  for (const d of openDeadlines(db, me, { withinDays: 0 }, localDate())) {
    if (d.days >= 0) continue
    const c = byClient.get(d.client_ref) ?? { ref: d.client_ref, client_name: d.client_name, overdue: 0, oldest_days_late: 0, deadlines: [] }
    c.overdue += 1
    c.oldest_days_late = Math.max(c.oldest_days_late, -d.days)
    c.deadlines.push(`${OBLIGATION_LABELS[d.obligation]} due ${d.due_date}`)
    byClient.set(d.client_ref, c)
  }
  return [...byClient.values()].sort((a, b) => b.oldest_days_late - a.oldest_days_late).slice(0, 15)
}

/** One open deadline as the assistant is given it: what, for whom, when, and how late or how soon. */
const deadlineForAssistant = (d: OpenDeadline): Record<string, unknown> => ({
  client_ref: d.client_ref,
  client_name: d.client_name,
  deadline: OBLIGATION_LABELS[d.obligation],
  due_date: d.due_date,
  when: d.days < 0 ? `${-d.days} days overdue` : d.days === 0 ? 'due today' : `due in ${d.days} days`,
  with: d.person ?? 'nobody yet'
})

